    'sms_setup_guide_title' => 'How to set up your SMS gateway',
    'sms_setup_guide_intro' => "These steps work for any SMS provider — Twilio, MSG91, Termii, Vonage, Fast2SMS, and others. You don't need to write any code. If you can copy and paste, you can finish in about five minutes.",

    'sms_setup_step1_title' => 'Step 1 — Pick a provider and grab your credentials',
    'sms_setup_step1_body' => 'Open an account with any SMS provider that delivers to the countries you serve. After signing up, log in to their dashboard and find these three things:',
    'sms_setup_step1_item1' => 'An API key (sometimes called Auth Token, Access Token, or Secret).',
    'sms_setup_step1_item2' => 'A sender ID or "From" number — this is what your customers see as the sender.',
    'sms_setup_step1_item3' => 'The API URL to send an SMS — usually shown on a "Send SMS" or "API reference" page.',

    'sms_setup_step2_title' => 'Step 2 — Find the "Send SMS" cURL example in their docs',
    'sms_setup_step2_body' => "Every provider's documentation includes a copy-paste cURL command that shows exactly how an SMS is sent. It looks something like this:",

    'sms_setup_step3_title' => 'Step 3 — Map the cURL into the form below',
    'sms_setup_step3_body' => 'Match each piece of the cURL command to a field in this form:',
    'sms_setup_table_curl' => 'In the cURL command',
    'sms_setup_table_form' => 'In this form',
