    'sms_setup_map_recipient_curl' => 'The recipient phone number',
    'sms_setup_map_message_curl' => 'The message text',

    'sms_setup_step4_title' => 'Step 4 — Pick the right Mobile Number Format',
    'sms_setup_step4_body' => 'Different providers expect the phone number in different shapes. Pick the matching option from the dropdown:',
    'sms_setup_step4_item1' => 'Twilio, Vonage, Plivo → "E.164 with +" (e.g. +919876543210).',
    'sms_setup_step4_item2' => 'MSG91, Termii, most Indian/African providers → "E.164 without +" (e.g. 919876543210).',
    'sms_setup_step4_item3' => 'Fast2SMS and other local-only providers → "National only" (e.g. 9876543210).',

    'sms_setup_step5_title' => 'Step 5 — Test before you save',
    'sms_setup_step5_body' => "Scroll to the bottom of the Custom SMS card, type a real phone number in the Test field, and click Send test SMS. If everything is wired correctly you will see a green popup and an SMS will arrive. If you see a red popup the popup also shows the provider's exact error — fix the highlighted header or body row and test again.",

